def transform(grid):
    """Recolor large solid rectangular patches to 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked = set()
    # Every patch is a contiguous, single-color rectangle. Find vertical
    # runs for each possible top row, and mark qualifying horizontal runs.
    for top in range(h):
        color = list(grid[top])
        active = [True] * w
        for bottom in range(top, h):
            if bottom > top:
                active = [active[c] and grid[bottom][c] == color[c]
                          for c in range(w)]
            height = bottom - top + 1
            if height < 4:
                continue
            c = 0
            while c < w:
                if not active[c]:
                    c += 1
                    continue
                v = color[c]
                end = c + 1
                while end < w and active[end] and color[end] == v:
                    end += 1
                width = end - c
                if width >= 4 and height * width >= 20:
                    for r in range(top, bottom + 1):
                        for x in range(c, end):
                            marked.add((r, x))
                c = end
    for r, c in marked:
        out[r][c] = 4
    return out
